<template>
    <section id="ChnageAddProject">
        <loader :is-visible="isLoading"></loader>
        <div id="ChnageAddProjectAgile" role="dialog" class="modal my-popups right fade">
            <div role="document" class="modal-dialog mw-1100">
                <div class="modal-content">
                    <div class="modal-header mheader-user">
                        <button type="button" class="close" v-on:click="CloseTemplate()"><em class="fa fa-times"
                                aria-hidden="true"></em></button>
                        <h4 class="modal-title" id="myModalLabel">{{ $t('AddProject') }}</h4>
                    </div>
                    <div class="modal-body newstepper">
                        <div class="stepper-wrap">
                            <div class="top-selection-strip"
                                v-if="form.industryId || form.methodologyId || form.projectName">
                                <span class="top-strip-label">
                                    <em class="fa fa-layer-group top-strip-label-icon"></em>
                                    Project Scope
                                </span>
                                <span class="top-strip-divider"></span>
                                <div class="top-chip-group">
                                    <span v-if="form.industryId" class="top-chip chip-industry">
                                        <span class="top-chip-icon-wrap"><em class="fa fa-briefcase"></em></span>
                                        <span class="top-chip-text">{{ selectedIndustryName }}</span>
                                    </span>
                                    <span v-if="form.methodologyId" class="top-chip-arrow">
                                        <em class="fa fa-chevron-right"></em>
                                    </span>
                                    <span v-if="form.methodologyId" class="top-chip chip-methodology">
                                        <span class="top-chip-icon-wrap"><em class="fa fa-tasks"></em></span>
                                        <span class="top-chip-text">{{ selectedMethodologyName }}</span>
                                    </span>
                                    <span v-if="form.projectName" class="top-chip-arrow">
                                        <em class="fa fa-chevron-right"></em>
                                    </span>
                                    <span v-if="form.projectName" class="top-chip chip-project">
                                        <span class="top-chip-icon-wrap"><em class="fa fa-folder-open"></em></span>
                                        <span class="top-chip-text">{{ form.projectName }}</span>
                                    </span>
                                </div>
                            </div>

                            <div class="stepper-header">
                                <div class="middle-line-track"></div>
                                <div class="middle-line-fill" :style="{ width: middleConnectorWidth }"></div>
                                <div v-for="(step, index) in steps" :key="step.id" class="step-item" :class="{
                                    active: currentStep === index + 1,
                                    completed: currentStep > index + 1
                                }">
                                    <div class="step-circle-wrap">
                                        <div class="step-ring" v-if="currentStep === index + 1"></div>
                                        <div class="step-circle">
                                            <em v-if="currentStep > index + 1" class="fa fa-check step-check-icon"></em>
                                            <span v-else class="step-number">{{ index + 1 }}</span>
                                        </div>
                                    </div>
                                    <p class="step-label">{{ step.label }}</p>
                                </div>
                                <div class="step-counter">
                                    <em class="fa fa-map-marker step-counter-icon"></em>
                                    Step {{ currentStep }} of {{ steps.length }}
                                </div>
                                <!-- <div class="step-progress-track"></div>
                                <div class="step-progress-fill" :style="{ width: stepProgressWidth }"></div> -->
                            </div>

                            <div class="step-content">
                                <div v-show="currentStep === 1">
                                    <div class="sc-panel">
                                        <div class="sc-panel-header sc-panel-header--industry">
                                            <span class="sc-panel-icon-wrap">
                                                <em class="fa fa-briefcase"></em>
                                            </span>
                                            <div class="sc-panel-title-group">
                                                <h6 class="sc-panel-title">Select Industry</h6>
                                                <p class="sc-panel-subtitle">Select the sector that best describes your project.</p>
                                            </div>
                                            <span v-if="form.industryId" class="sc-panel-selected-chip">
                                                <em class="fa fa-check"></em> {{ selectedIndustryName }}
                                            </span>
                                        </div>
                                        <div class="sc-panel-body">
                                            <div class="card-grid card-grid--industry">
                                                <div v-for="industry in industries" :key="industry.id"
                                                    class="select-card industry-card"
                                                    :class="{ selected: form.industryId === industry.id }"
                                                    @click="GetTemplateListData(industry)">
                                                    <em v-if="form.industryId === industry.id"
                                                        class="fa fa-check-circle check-badge"></em>
                                                    <div class="card-head industry-icon-wrap">
                                                        <em :class="industry.icon" class="industry-icon"></em>
                                                    </div>
                                                    <p class="name industry-name">{{ industry.name }}</p>
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    <div class="sc-panel" :class="{ 'sc-panel--locked': !form.industryId }">
                                        <div class="sc-panel-header sc-panel-header--methodology">
                                            <span class="sc-panel-icon-wrap sc-panel-icon-wrap--method">
                                                <em class="fa fa-tasks"></em>
                                            </span>
                                            <div class="sc-panel-title-group">
                                                <h6 class="sc-panel-title">Select Methodology</h6>
                                                <p class="sc-panel-subtitle">Select a project template that fits your workflow.</p>
                                            </div>
                                            <span v-if="form.methodologyId" class="sc-panel-selected-chip sc-panel-selected-chip--method">
                                                <em class="fa fa-check"></em> {{ selectedMethodologyName }}
                                            </span>
                                            <span v-if="!form.industryId" class="sc-panel-lock-badge">
                                                <em class="fa fa-lock"></em> Select an industry first
                                            </span>
                                        </div>
                                        
                                        <div class="sc-panel-body">
                                            <div v-if="methodologies.length > 0" class="card-grid card-grid--method">
                                                <div v-for="method in methodologies" :key="method.id"
                                                    class="select-card method-card" :class="{
                                                        selected: form.methodologyId === method.id,
                                                        disabled: !form.industryId
                                                    }" @click="selectMethodology(method.id)">
                                                    <div v-if="method.imageUrls && method.imageUrls.length"
                                                        class="method-card-img-wrap"
                                                        @click.stop="openLightbox(method.imageUrls)">
                                                        <img :src="method.imageUrls[0]" :alt="method.name" class="method-card-img" />
                                                        <span v-if="method.imageUrls.length > 1" class="method-card-img-count">
                                                            {{ method.imageUrls.length }}
                                                        </span>
                                                        <span class="method-card-img-zoom"><em class="fa fa-search-plus"></em></span>
                                                    </div>
                                                    <div class="method-card-inner">
                                                        <div class="method-icon-wrap">
                                                            <em :class="method.icon" class="left-card-icon"></em>
                                                        </div>
                                                        <div class="method-card-text">
                                                            <p class="name mb-0">{{ method.name }}</p>
                                                            <p class="desc mb-0" v-if="method.description">{{ method.description }}</p>
                                                        </div>
                                                    </div>
                                                    <span v-if="form.methodologyId === method.id"
                                                        class="method-card-selected-tick" aria-hidden="true">
                                                        <em class="fa fa-check"></em>
                                                    </span>
                                                </div>
                                            </div>

                                            <div v-if="methodologies.length === 0" class="methodology-placeholder">
                                                <span class="methodology-placeholder-icon-wrap">
                                                    <em class="fa fa-hand-pointer-o"></em>
                                                </span>
                                                <p class="methodology-placeholder-title">No methodologies yet</p>
                                                <p class="methodology-placeholder-hint">Pick an industry above to load available project templates.</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div v-show="currentStep === 2">
                                    <div class="project-page-head">
                                        <div class="step-title-row">
                                            <h5 class="step-title mb-0">Project Details</h5>
                                            <button type="button" class="btn btn-info"
                                                :class="{ 'is-mandatory': IsMandatory }" @click="toggleFieldMode">
                                                <em class="fa" :class="IsMandatory ? 'fa-check-circle' : 'fa-sliders'"></em>
                                                {{ IsMandatory ? 'Mandatory Fields' : 'Advanced Field' }}
                                            </button>
                                        </div>
                                    </div>
                                    <Form ref="AddProject" class="float-left w-100 tab-content py-2 px-3">
                                        <dynamic-form lang="en" ref="AddProjectForm" :schema="FormSchema"
                                            :mandatorytext='MandatoryString'>                                        
                                            <template v-slot:tgslot-off_days="{ data }">
                                                <div class="w-100 border-0 bg-transparent offdays">
                                                    <ul class="ks-cboxtags p-0">
                                                        <li v-for="(option, indexx) in data.fieldInfo.config.options"
                                                            :key="indexx">
                                                            <div class="custom-control custom-checkbox">
                                                                <input type="checkbox"
                                                                    :id="`chk_${data.fieldInfo.customFieldId}_${indexx}`"
                                                                    class="custom-control-input" style="display: none;"
                                                                    :checked="isChecked(option.value, data.fieldInfo.value)"
                                                                    @change="toggleValue(option.value, data.fieldInfo)" />
                                                                <label
                                                                    class="custom-control-label universal-custom-control-label pt-1"
                                                                    :for="`chk_${data.fieldInfo.customFieldId}_${indexx}`"
                                                                    :class="{ active: isChecked(option.value, data.fieldInfo.value) }">{{
                                                                        option.name }}</label>
                                                            </div>
                                                        </li>
                                                    </ul>
                                                </div>
                                                </template>
                                                <template v-slot:tgslot-estimated_hours="{ data }">
                                                    <input
                                                        type="text"
                                                        class="form-control"
                                                        :value="data.fieldInfo.value"
                                                        @input="onDecimalInput($event, data.fieldInfo)"
                                                        placeholder="Enter Project Hours"
                                                        :disabled="IsDeisabled"
                                                    />
                                                </template>
                                                    <template v-slot:tgslot-base_rate="{ data }">
                                                    <input
                                                        type="text"
                                                        class="form-control"
                                                        :value="data.fieldInfo.value"
                                                        @input="onDecimalInput($event, data.fieldInfo)"
                                                        placeholder="Enter Project Rate"
                                                        :disabled="IsDeisabled"
                                                    />
                                                </template>
                                                    <template v-slot:tgslot-estimated_cost="{ data }">
                                                    <input
                                                        type="text"
                                                        class="form-control"
                                                        :value="data.fieldInfo.value"
                                                        @input="onDecimalInput($event, data.fieldInfo)"
                                                        placeholder="Enter Project Amount"
                                                    />
                                              </template>
                                                <template v-slot:tgslot-project_description="{ data }">
                                                    <ckeditor :editor="editor" @ready="onReady" v-model="Descriptionn">
                                                    </ckeditor>
                                                </template>
                                            </dynamic-form>
                                    </Form>
                                </div>

                                <div v-show="currentStep === 3">
                                    <div class="tabs-page-head">
                                        <span class="sc-panel-icon-wrap sc-panel-icon-wrap--tabs">
                                            <em class="fa fa-columns"></em>
                                        </span>
                                        <div class="sc-panel-title-group">
                                            <p class="sc-panel-title mb-0">Views &amp; Tabs</p>
                                            <p class="sc-panel-subtitle mb-0">Choose the views and tabs for your project workspace</p>
                                        </div>
                                        <span class="locked-badge ml-auto">
                                            <em class="fa fa-lock"></em> Locked tabs are mandatory &amp; pre-selected. Add more as needed.
                                        </span>
                                    </div>

                                    <div class="tabs-grid">
                                        <div v-for="tab in viewsAndTabs" :key="tab.id" class="tab-card" :class="{
                                            selected: isTabSelected(tab),
                                            locked: tab.isMandatory
                                        }" @click="toggleTab(tab)">
                                            <div class="tab-center-wrap">
                                                <span class="tab-icon">
                                                    <em :class="tab.feature_icon" class='fa'></em>
                                                </span>
                                                <p class="tab-title">{{$t(getTabDisplayName(selectedIndustryName,tab.feature)) }}</p>
                                            </div>
                                            <span v-if="isTabSelected(tab)"
                                                class="tab-pill tab-pill-selected tab-pill-top">
                                                <em class="fa fa-check"></em>
                                            </span>
                                            <span v-if="tab.isMandatory" class="tab-pill tab-pill-locked tab-pill-bottom">
                                                <em class="fa fa-lock"></em>
                                            </span>
                                        </div>
                                    </div>
                                </div>

                                <div v-show="currentStep === 4" class="team-step">

                                    <div class="sc-panel-header sc-panel-header--industry">
                                   <span class="sc-panel-icon-wrap">
                                     <em class="fa fa-users"></em></span>
                                    <div class="sc-panel-title-group">
                                     <h6 class="sc-panel-title">Assign Team</h6>
                                      <p class="sc-panel-subtitle">Add team members and designate a Project Manager.</p></div>
                                    </div>




                                    <!-- <div class="team-page-head">
                                        <h5 class="step-title mb-0">Assign Team</h5>
                                        <p class="team-step-subtitle">Add team members and designate a Project Manager.</p>
                                    </div> -->




                                    <div class="team-mode-bar mt-2">
                                        <label class="team-mode-option">
                                            <input type="radio" value="user" v-model="teamType" @change="onTeamTypeChange">
                                            <span>User</span>
                                        </label>
                                        <label class="team-mode-option ml-12">
                                            <input type="radio" value="team" v-model="teamType" @change="onTeamTypeChange">
                                            <span>Team</span>
                                        </label>
                                        <button v-if="teamType === 'team'" type="button" class="btn btn-add-team" @click="AddTeamProject">
                                            <em class="fa fa-plus"></em> Add Team
                                        </button>
                                    </div>
                                    <div class="selected-users-box" v-if="teamType === 'user' && selectedTeamMembers.length">
                                        <p class="selected-title">{{ selectedTeamMembers.length }} members selected</p>
                                        <div class="selected-chips">
                                            <span class="member-chip member-chip-rich"
                                                v-for="member in selectedTeamMembers" :key="member.USER_ID">
                                                <span class="member-avatar-small"
                                                    :class="'avatar-tone-' + (member.USER_ID % 5)">{{ memberInitials(member)
                                                    }}</span>
                                                <span class="member-chip-name">{{ member.MEMBERNAME }}</span>
                                                <span v-if="isPMSelected(member.USER_ID)" class="pm-badge-chip">PM</span>
                                                <em class="fa fa-times chip-close"
                                                    @click.stop="toggleTeamMember(member.USER_ID)"></em>
                                            </span>
                                        </div>
                                    </div>
                                    <div class="selected-users-box" v-if="teamType === 'team' && selectedTeams.length">
                                        <p class="selected-title">{{ selectedTeams.length }} teams selected</p>
                                        <div class="selected-chips">
                                            <span class="member-chip member-chip-rich" v-for="team in selectedTeams"
                                                :key="team.TEAM_ID || team.team_id || team.id">
                                                <span class="member-avatar-small"
                                                    :class="'avatar-tone-' + ((team.TEAM_ID || team.team_id || team.id) % 5)">
                                                    {{ String(team.TEAM_NAME || team.team_name || team.name || 'T').substring(0, 2).toUpperCase() }}
                                                </span>
                                                <span class="member-chip-name">{{ team.TEAM_NAME || team.team_name || team.name }}</span>
                                                <em class="fa fa-times chip-close" @click.stop="toggleTeamGroupSelection(team)"></em>
                                            </span>
                                        </div>
                                    </div>
                                    <div class="team-search-wrap" v-if="teamType === 'user'">
                                        <em class="fa fa-search team-search-icon" aria-hidden="true"></em>
                                        <input type="text" class="form-control team-search-input"
                                            placeholder="Search by name or department..." v-model.trim="teamSearch">
                                    </div>
                                    <div class="table-responsive team-table-wrap team-table-pretty-wrap" v-if="teamType === 'user'">
                                        <table class="table team-table team-table-pretty">
                                            <thead class="thead-bg">
                                                <tr>
                                                    <th class="col-select">Select</th>
                                                    <th>Name</th>
                                                    <th>Department</th>
                                                    <th>Designation</th>
                                                    <th class="col-pm">PM</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr v-for="(member,index) in filteredTeamMembers" :key="member.USER_ID"
                                                    :class="{ 'row-selected': isTeamSelected(member.USER_ID) }">
                                                    <td class="td-select">
                                                        <input type="checkbox" class="team-checkbox"
                                                            :checked="isTeamSelected(member.USER_ID)"
                                                            @change="toggleTeamMember(member.USER_ID)" :disabled="member.USER_ID == userId">
                                                    </td>
                                                    <td>
                                                        <div class="table-name-cell">
                                                            <span class="member-avatar-table"
                                                                :class="'avatar-tone-' + (member.USER_ID % 5)">{{
                                                                memberInitials(member) }}</span>
                                                            <span class="table-member-name">{{ member.MEMBERNAME }}</span>
                                                        </div>
                                                    </td>
                                                    <td class="td-muted">{{ member.DEPARTMENT }}</td>
                                                    <td class="td-muted">{{ member.DESIGNATION }}</td>
                                                    <td class="td-pm">
                                                        <input v-if="isTeamSelected(member.USER_ID)" type="checkbox"   
                                                            class="team-radio" :checked="isPMSelected(member.USER_ID)"
                                                            @change="togglePM(member)">
                                                        <span v-else class="pm-placeholder">—</span>
                                                    </td>
                                                </tr>
                                                <tr v-if="!filteredTeamMembers.length">
                                                    <td colspan="5" class="no-record-row">No record found</td>
                                                </tr>
                                            </tbody>
                                        </table>
                                    </div>
                                    <div class="team-search-wrap" v-if="teamType === 'team'">
                                        <em class="fa fa-search team-search-icon" aria-hidden="true"></em>
                                        <input type="text" class="form-control team-search-input"
                                            placeholder="Search team..." v-model.trim="teamSearch">
                                    </div>
                                    <div class="table-responsive team-table-wrap team-table-pretty-wrap" v-if="teamType === 'team'">
                                        <table class="table team-table team-table-pretty">
                                            <thead class="thead-bg">
                                                <tr>
                                                    <th class="col-select">Select</th>
                                                    <th>Team Name</th>
                                                    <th>{{$t('TeamLead')}}</th>
                                                    <th class="text-center">{{$t('Action')}}</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr v-for="team in filteredTeams" :key="team.TEAM_ID || team.team_id || team.id">
                                                    <td class="td-select">
                                                        <input type="checkbox" class="team-checkbox"
                                                            :checked="isTeamGroupSelected(team)"
                                                            @change="toggleTeamGroupSelection(team)">
                                                    </td>
                                                    <td class="td-muted">{{ team.TEAM_NAME || team.team_name || team.name || '-' }}</td>
                                                    <td class="td-muted">{{ team.TEAM_LEAD }}</td>
                                                    <td class="text-center single-action"><span  @click="ShowTeamMember(team.TEAM_ID)"><em class="fa fa-eye text-primary cursor-pointer"></em></span>
                                                        <span  @click="commonDeleteData(team.TEAM_ID)"><em class="fa fa-trash-o action-icon text-danger  cursor-pointer ml-2"></em></span>
                                                    </td>
                                                </tr>
                                                <tr v-if="!filteredTeams.length">
                                                    <td colspan="3" class="no-record-row">No record found</td>
                                                </tr>
                                            </tbody>
                                        </table>
                                    </div>
                                </div>

                                <div v-show="currentStep === 5">
                                    <!-- <div class="review-page-head">
                                        <h5 class="step-title mb-0">Review & Create</h5>
                                        <p class="review-subtitle">Review your project configuration before creating.</p>
                                    </div> -->

                                      <div class="sc-panel-header sc-panel-header--industry mb-2">
                                        <span class="sc-panel-icon-wrap">
                                          <em class="fa fa-cogs"></em></span>
                                         <div class="sc-panel-title-group">
                                             <h6 class="sc-panel-title">Review & Create</h6>
                                             <p class="sc-panel-subtitle">Review your project configuration before creating.</p>
                                        </div>
                                    </div>



                                    <div class="review-box review-box-pretty">
                                        <div class="review-head">
                                            <h6>1. Industry & Methodology</h6>
                                            <!-- <a href="javascript:void(0)" @click="goToStep(1)"
                                                class="review-edit-link">Edit</a> -->

                                                <a href="javascript:void(0)" @click="goToStep(1)">
                                                    <em class="fa fa-pencil text-success"></em>
                                                </a>
                                        </div>
                                        <div class="review-row"><span class="review-key">Industry</span><span
                                                class="review-val">{{ selectedIndustryName
                                                }}</span></div>
                                        <div class="review-row"><span class="review-key">Template</span><span
                                                class="review-val">{{
                                                selectedMethodologyName }}</span></div>
                                    </div>
                                    <div class="review-box review-box-pretty">
                                        <div class="review-head">
                                            <h6>2. Project Details</h6>
                                            <!-- <a href="javascript:void(0)" @click="goToStep(2)"
                                                class="review-edit-link">Edit</a> -->

                                                <a href="javascript:void(0)" @click="goToStep(2)">
                                                    <em class="fa fa-pencil text-success"></em>
                                                </a>
                                        </div>
                                        <div class="review-grid-2">
                                            <div class="review-row"><span class="review-key">Name</span><span
                                                    class="review-val">{{ form.projectName ||
                                                    '-' }}</span></div>
                                            <div class="review-row"><span class="review-key">Start Date</span><span
                                                    class="review-val">{{ form.startDate
                                                    || '-' }}</span></div>
                                            <div class="review-row"><span class="review-key">End Date</span><span
                                                    class="review-val">{{ form.endDate ||
                                                    '-' }}</span></div>
                                            <div class="review-row"><span class="review-key">Status</span><span
                                                    class="review-val">
                                                    <span class="status-pill">{{ form.statusName || 'Not specified' }}</span>
                                                </span></div>
                                            <div class="review-row"><span class="review-key">Priority</span><span
                                                    class="review-val"><span class="priority-pill">{{ form.priorityName
                                                        }}</span></span></div>
                                        </div>
                                    </div>
                                    <div class="review-box review-box-pretty">
                                        <div class="review-head">
                                            <h6>3. Views & Tabs</h6>
                                            <!-- <a href="javascript:void(0)" @click="goToStep(3)"
                                                class="review-edit-link">Edit</a> -->

                                                <a href="javascript:void(0)" @click="goToStep(3)">
                                                    <em class="fa fa-pencil text-success"></em>
                                                </a>
                                        </div>
                                        <div class="review-row"><span class="review-key">Selected Views</span><span
                                                class="review-val">{{
                                                form.selectedTabs.length  }} views enabled</span></div>
                                        <div class="review-row"><span class="review-key">Views</span><span
                                                class="review-val">{{ selectedTabsText
                                                }}</span></div>
                                    </div>
                                    <div class="review-box review-box-pretty">
                                        <div class="review-head">
                                            <h6>4. Team</h6>
                                            <!-- <a href="javascript:void(0)" @click="goToStep(4)"
                                                class="review-edit-link">Edit</a> -->

                                                <a href="javascript:void(0)" @click="goToStep(4)">
                                                    <em class="fa fa-pencil text-success"></em>
                                                </a>
                                        </div>
                                        <div v-if="teamType != 'team'">
                                        <div class="review-row"><span class="review-key">Members</span><span
                                                class="review-val">{{
                                                selectedTeamMembers.length }} members</span></div>
                                        <div class="review-row"><span class="review-key">Project Manager</span><span
                                                class="review-val">{{
                                                selectedPmName }}</span></div>

                                        </div>
                                        <div v-else="teamType == 'team'">
                                        <div class="review-row">
                                            <span class="review-key">Total Teams</span>
                                            <span class="review-val">
                                                {{ selectedTeams.length }}
                                            </span>
                                        </div>

                                        <div class="review-row">
                                            <span class="review-key">Team Names</span>
                                            <span class="review-val">
                                                {{ selectedTeams.map(t => t.TEAM_NAME).join(', ') || '-' }}
                                            </span>
                                        </div>
                                    </div>
                                    </div>
                                </div>
                            </div>

                            <div class="footer-actions">
                                <div class="footer-left" v-if="currentStep > 1">
                                    <button type="button" class="btn btn-secondary mr-1" @click="prevStep">
                                        <em class="fa fa-angle-double-left"></em> Back
                                    </button>
                                </div>
                                <div class="footer-right">
                                    <button type="button" class="btn btn-danger mr-2"  @click="CloseTemplate">
                                         <em class="fa fa-close pr-2"></em>Cancel
                                    </button>
                                    <button v-if="currentStep < 5" type="button" class="btn btn-primary"
                                        @click="nextStep">
                                        Next <em class="fa fa-angle-double-right pl-2"></em>
                                    </button>
                                    <button v-else type="button" class="btn btn-success"
                                        @click="SaveProject">
                                        <em class="fa fa-check pr-2"></em>Create Project 
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <AddPriority v-if="isPriority" @updatedata="UpdateSelectJson"></AddPriority>
        <AddProjectPopupTeam v-if="isShowProjectPopupTeam"></AddProjectPopupTeam>
        <AssociateUser v-if="IsUser" :TeamId="TeamId" :TabsArray="TabsArray"></AssociateUser>
    </section>
</template>
<script>
import DataService from '../../services/DataService'
import AddPriority from './AddPriority.vue'
import AssociateUser from './AssociateUser.vue'
import AddProjectPopupTeam from './AddProjectPopupTeam.vue';
export default {
    components: { AddPriority,AssociateUser,AddProjectPopupTeam },
    data() {
        return {
            isShowProjectPopupTeam:false,
            TabsArray:[],
            isPriority: false,
            isLoading: false,
            FormSchema: [],
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            editor: this.CLASSIC_EDITOR,
            Descriptionn: '',
            currentStep: 1,
            teamSearch: '',
            steps: [
                { id: 1, label: 'Industry & Template' },
                { id: 2, label: 'Project Details' },
                { id: 3, label: 'Views & Tabs' },
                { id: 4, label: 'Team' },
                { id: 5, label: 'Review & Create' }
            ],
            industries: [],
            methodologies: [],
            viewsAndTabs: [],
            teamMembers: [],
            teamData: [],
            ProjectId: 0,
            form: {
                industryId: null,
                methodologyId: null,
                projectName: '',
                description: '',
                startDate: '',
                endDate: '',
                statusId: '',
                statusName:'',
                priorityName:'',
                priority: '',
                selectedTabs: [],
                selectedTeamIds: [],
                selectedTeamGroupIds: [],
                pmIds: []
            },
            IsMandatory: false,
            PStartDate: null,
            PEndDate: null,
            Currency: '',
            userId: null,
            companyId: null,
            UserType: null,
            teamType: 'user',
            IsUser:false,
            TeamId:null,
            CurrencyCode:'',
            IsDeisabled:true,
            defaultCurrency:''
        };
    },
    mounted: function () {
        this.GetIndustryType();
        this.ProjectBaseRate();
        this.FetchProjectData();
    },
    created: async function () {
        var ths = this;
        ths.userId = ths.GetUserInfo.ID;
        ths.companyId = ths.GetUserInfo.CompanyId;
        ths.UserType = ths.GetUserInfo.UserType;
        ths.Currency = ths.CurrencyCode==""?ths.GetUserInfo.Currency:ths.CurrencyCode;
        let PStartDate = new Date();
        let PEndDate = new Date();
        PEndDate.setDate(PStartDate.getDate() + 7);
        ths.PStartDate = PStartDate;
        ths.PEndDate = PEndDate;
        if (ths.teamType == "user") {
            await ths.FetchMemberListing();
        }
        const josnData = JSON.parse(localStorage.getItem('industryType'));
        ths.form.industryId = (josnData.DATA[0].Industry_Type_Id !== null && josnData.DATA[0].Industry_Type_Id !== false) ? josnData.DATA[0].Industry_Type_Id : 0;
        if (this.form.industryId > 0) {
         this.GetTemplateListData({ id: this.form.industryId });
         }
    },
    computed: {
        selectedIndustryName() {
            const selected = this.industries.find((item) => item.id === this.form.industryId);
            return selected ? selected.name : '-';
        },
        selectedMethodologyName() {
            const selected = this.methodologies.find((item) => item.id === this.form.methodologyId);
            return selected ? selected.name : '-';
        },
        stepProgressWidth() {
            const percent = (this.currentStep / this.steps.length) * 100;
            return `${percent}%`;
        },
        middleConnectorWidth() {
            const ratio = (this.currentStep - 1) / (this.steps.length - 1);
            return `calc(80% * ${ratio})`;
        },
        selectedTabsText() {
            if (!this.form.selectedTabs.length && !this.viewsAndTabs.some(item => item.isMandatory)) {
                return '-';
            }

            return this.viewsAndTabs
                .filter(item =>
                    this.form.selectedTabs.includes(item.id) || item.isMandatory === true)
                .map(item => item.feature)
                .join(', ');
        },
        filteredTeamMembers() {
            const search = (this.teamSearch || '').toLowerCase().trim();
            if (!search) {
                return this.teamMembers;
            }
            return this.teamMembers.filter((member) => {
                const memberName = String(member.MEMBERNAME || member.name || '').toLowerCase();
                const department = String(member.DEPARTMENT || member.department || '').toLowerCase();

                return memberName.indexOf(search) > -1 || department.indexOf(search) > -1;
            });
        },
        filteredTeams() {
            const search = (this.teamSearch || '').toLowerCase().trim();
            if (!search) return this.teamData;
            return (this.teamData || []).filter((team) => {
                const name = String(team.TEAM_NAME || team.team_name || team.name || '').toLowerCase();
                return name.indexOf(search) > -1;
            });
        },
        selectedTeams() {
            return (this.teamData || []).filter((team) => {
                const id = team.TEAM_ID || team.team_id || team.id;
                return this.form.selectedTeamGroupIds.indexOf(id) > -1;
            });
        },
        selectedTeamText() {
            if (!this.form.selectedTeamIds.length) {
                return 'No member selected';
            }
            return this.teamMembers
                .filter((item) => this.form.selectedTeamIds.indexOf(item.USER_ID) > -1)
                .map((item) => item.MEMBERNAME)
                .join(', ');
        },
        selectedTeamMembers() {
            return this.teamMembers.filter((item) => this.form.selectedTeamIds.indexOf(item.USER_ID) > -1);
        },
        selectedPmName() {
            const pmMembers = this.teamMembers.filter((item) => this.form.pmIds.indexOf(item.USER_ID) > -1);
            if (!pmMembers.length) return 'Not selected';
            return pmMembers.map((item) => item.MEMBERNAME || item.name || '').join(', ');
        }
    },
    methods: {
        UpdateSelectJson: function (name, json) {
            let ths = this;
            ths.FormSchema.forEach((group) => {
                group.Data.forEach((field) => {
                    if (field.name == name) {
                        if (json != null) {
                            field.config.options = [];
                            json.forEach(x => {
                                var Obj = {
                                    name: x.name,
                                    value: x.value
                                }
                                field.config.options.push(Obj);
                            })
                        }
                    }
                })
            })
            ths.$refs.AddProjectForm.UpdateKeyValue();
        },
        commonDeleteData: async function(val) {
            var vm = this;
            var url = 'controller=Team&action=Delete'            
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.isLoading = true;
                                        
                    if (val != null && val != "") {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                            var postJSON = {
                                ids: val,
                                moduleName: "PROJECT",
                                subModuleCode: "DELETE_PROJECT_TEAM",
                                refCode: 'DELETE_PROJECT_TEAM'
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                vm.isLoading = false;
                                if (response.data.length > 0) {
                                    if (response.data[0].Status == 'Success') {
                                        if (response.data[0].Code == 'BACKLOG_ASSIGN') {
                                            vm.ShowAlert(vm.$t('proceedingwithdeletion', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                                        } else {
                                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                                        }
                                        vm.FetchTeamListing();
                                    }
                                    else {
                                        vm.ShowAlert(vm.$t('DeletedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                                    }
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), "warning", true, vm.$t("Alert"));
                    }
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
            vm.isLoading = false;
        },
        parseMethodologyImageUrls(x) {
            const DEFAULT = 'https://cogniterblob.blob.core.windows.net/global/GlobalImages/Project/SoftwareDevelopmentTemplate/Scrum/Scrum.png'
            const raw = x.ImagePath || x.IMAGE_URL || x.image_url || x.ImageUrl || x.IMAGES || x.images
            let parts = []
            if (Array.isArray(raw)) {
                parts = raw.map((u) => String(u).trim()).filter(Boolean)
            } else if (raw != null && String(raw).trim() !== '') {
                parts = String(raw).split(',').map((s) => s.trim()).filter(Boolean)
            }
            if (!parts.length) parts = [DEFAULT]
            return parts
        },
        ShowTeamMember(id) {
            this.TeamId = id;
            this.IsUser = true;
        },
       async AddTeamProject() {
            var url = 'controller=Team&action=Add';            
            var vm =this;
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
            this.isShowProjectPopupTeam = true;
            }
                else {
              vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        GetTemplateListData: async function (itm) {            
            const vm = this;
            if (!itm || !itm.id) return;
            const industryChanged = vm.form.industryId !== itm.id;
            vm.isLoading = true;
            vm.form.industryId = itm.id;
            if (industryChanged) {
                vm.form.methodologyId = null;
                vm.resetTabsForTemplateChange();
            }
            const url = `IndustryTypeId=${itm.id}`;
            await DataService.GetTemplateListData(url).then((response) => {
                vm.isLoading = false;
                const result = response && response.data && response.data.result ? response.data.result : null;
                const list = result && result.DATA ? result.DATA : [];                
                vm.methodologies = (list || []).map((x, idx) => {
                    const name = x.name || x.TEMPLATE_NAME || x.TemplateName || x.template_name || '';
                    return {
                        id: x.id || x.TEMPLATE_ID || x.template_id || x.TemplateId || idx + 1,
                        name,
                        description: x.description || x.TEMPLATE_DESCRIPTION || x.template_description || '',
                        icon: vm.getMethodologyIcon(name, idx),
                        imageUrls: vm.parseMethodologyImageUrls(x)
                    };
                });
            }).catch(() => {
                vm.isLoading = false;
                vm.methodologies = [];
                if (industryChanged) {
                    vm.form.methodologyId = null;
                }
            });
        },
        openLightbox(urlsOrUrl) {
            this.closeLightbox();
            const urls = Array.isArray(urlsOrUrl)
                ? urlsOrUrl.filter((u) => u && String(u).trim())
                : urlsOrUrl ? [String(urlsOrUrl).trim()] : [];
            if (!urls.length) return;

            let index = 0;
            const vm = this;

            const overlay = document.createElement('div');
            overlay.id = 'method-lightbox-portal';
            overlay.className = 'method-lightbox-overlay';
            const box = document.createElement('div');
            box.className = 'method-lightbox-box';

            const closeBtn = document.createElement('button');
            closeBtn.type = 'button';
            closeBtn.className = 'method-lightbox-close';
            closeBtn.innerHTML = '<em class="fa fa-times"></em>';
            closeBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                vm.closeLightbox();
            });

            const img = document.createElement('img');
            img.className = 'method-lightbox-img';
            img.alt = '';

            const counter = document.createElement('div');
            counter.className = 'method-lightbox-counter';

            const prevBtn = document.createElement('button');
            prevBtn.type = 'button';
            prevBtn.className = 'method-lightbox-nav method-lightbox-prev';
            prevBtn.innerHTML = '<em class="fa fa-chevron-left"></em>';
            prevBtn.setAttribute('aria-label', 'Previous');

            const nextBtn = document.createElement('button');
            nextBtn.type = 'button';
            nextBtn.className = 'method-lightbox-nav method-lightbox-next';
            nextBtn.innerHTML = '<em class="fa fa-chevron-right"></em>';
            nextBtn.setAttribute('aria-label', 'Next');

            const update = () => {
                img.src = urls[index];
                const multi = urls.length > 1;
                counter.style.display = multi ? 'block' : 'none';
                if (multi) counter.textContent = `${index + 1} / ${urls.length}`;
                prevBtn.style.display = multi && index > 0 ? 'flex' : 'none';
                nextBtn.style.display = multi && index < urls.length - 1 ? 'flex' : 'none';
            };

            prevBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                if (index > 0) {
                    index--;
                    update();
                }
            });
            nextBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                if (index < urls.length - 1) {
                    index++;
                    update();
                }
            });

            const onKey = (e) => {
                if (e.key === 'Escape') vm.closeLightbox();
                if (urls.length > 1) {
                    if (e.key === 'ArrowLeft' && index > 0) {
                        index--;
                        update();
                    }
                    if (e.key === 'ArrowRight' && index < urls.length - 1) {
                        index++;
                        update();
                    }
                }
            };
            document.addEventListener('keydown', onKey);
            overlay._methodLightboxKeyHandler = onKey;

            box.appendChild(closeBtn);
            box.appendChild(prevBtn);
            box.appendChild(nextBtn);
            box.appendChild(img);
            box.appendChild(counter);
            overlay.appendChild(box);
            document.body.appendChild(overlay);

            overlay.addEventListener('click', () => vm.closeLightbox());
            box.addEventListener('click', (e) => e.stopPropagation());

            update();
        },
        onDecimalInput(event, fieldInfo) {
            let value = event.target.value;
            value = value.replace(/[^0-9.]/g, '');
            const parts = value.split('.');
            if (parts.length > 2) {
            value = parts[0] + '.' + parts[1];
            }
            if (parts[1]) {
            value = parts[0] + '.' + parts[1].substring(0, 2);
            }
            fieldInfo.value = value;
            event.target.value = value;
            if (fieldInfo.name === 'estimated_hours') {
            this.GetProjectAmount(fieldInfo, 'ProjectHours');
        } 
        else if (fieldInfo.name === 'base_rate') {
            this.GetProjectAmount(fieldInfo, 'BaseRate');
  }
        },
        GetProjectAmount: function (typevalue, type) {
            var vm = this;
            var baseRate = 0;
            var projectHours = 0;
            var ProjectAmount = 0;
            vm.FormSchema.forEach((group) => {
                if (type == 'ProjectHours') {
                    $.each(group.Data, $.proxy(function (index, item) {
                        if (item.name == "base_rate") {
                            baseRate = item.value;
                            if (typevalue.value == "" || typeof typevalue.value == "undefined" || typevalue.value == null) {
                                ProjectAmount = 0 * baseRate;
                            }
                            else {
                                ProjectAmount = (parseFloat(typevalue.value) * baseRate).toFixed(2);
                            }
                        }
                    }));
                } else {
                    $.each(group.Data, $.proxy(function (index, item) {
                        if (item.name == "estimated_hours") {
                            projectHours = item.value;
                            if (typevalue.value == "" || typeof typevalue.value == "undefined" || typevalue.value == null) {
                                ProjectAmount = 0 * projectHours;
                            }
                            else {
                                ProjectAmount = (parseFloat(typevalue.value) * projectHours).toFixed(2);
                            }
                        }
                    }));
                }
                $.each(group.Data, $.proxy(function (index, item) {
                    if (item.name == "estimated_cost") {
                        item.value = ProjectAmount;
                        item.validationRules.required = false;
                    }
                }));
            })
        },
        closeLightbox() {
            const el = document.getElementById('method-lightbox-portal');
            if (el && el._methodLightboxKeyHandler) {
                document.removeEventListener('keydown', el._methodLightboxKeyHandler);
            }
            if (el) el.remove();
        },
        getMethodologyIcon(name, idx) {
            const n = (name || '').toLowerCase();
            if (n.includes('scrum')) return 'fa fa-refresh text-info';
            if (n.includes('kanban')) return 'fa fa-clipboard text-muted';
            if (n.includes('bug')) return 'fa fa-bug text-success';
            if (n.includes('agile')) return 'fa fa-bolt text-warning';
            return idx % 2 === 0 ? 'fa fa-th-large text-info' : 'fa fa-list-alt text-muted';
        },
        SaveProject() {
            var ths = this;
            ths.isLoading = true;
            var team = [];
            var CustomFieldArray = ths.$refs.AddProjectForm.ConvertDynamicFormObjToCustomFieldObj(ths.FormSchema);
            if (parseInt(ths.ProjectId) == 0) {
                if (ths.teamType == 'team') {
                    ths.selectedTeams.forEach((item) => {
                        var teamObj = {
                            team_id: item.USER_ID == undefined ? item.TEAM_ID : item.USER_ID,
                            status_id: 1001
                        }
                        team.push(teamObj)
                    })
                    let obj = {
                        custom_field_id: 0,
                        field_name: 'project_team_type',
                        field_value: ths.teamType
                    }
                    CustomFieldArray.push(obj);
                }
                else {
                    const resultString = ths.selectedTeamMembers.map(item => item.USER_ID).join(',');
                    const userIds = resultString.split(',');
                    var teamData = ths.filteredTeamMembers.filter(member => userIds.includes(member.USER_ID.toString()));
                    teamData.forEach((itm) => {
                        var teamObj = {
                            user_id: itm.USER_ID,
                            sold_horly_rate: itm.ratePerHour,
                            designation_id: null,
                            user_type_id: itm.ShowIsPM ? 2 : (itm.USER_TYPE_ID === 2 ? 3 : itm.USER_TYPE_ID),
                            alias_name: itm.ALIASNAME,
                            is_show_alias: itm.CheckAliasName == true ? true : false,
                            status_id: 1001,
                        }
                        
                        team.push(teamObj)
                    });
                    let filteredData = ths.teamMembers.filter(member => member.USER_ID === ths.userId);
                    if (filteredData.length > 0) {
                        var userExists = team.some(item => item.user_id === filteredData[0].USER_ID);
                        if (!userExists) {
                            team.push({
                                user_id: filteredData[0].USER_ID,
                                sold_horly_rate: filteredData[0].ratePerHour,
                                designation_id: null,
                                user_type_id: 2,
                                alias_name: filteredData[0].ALIASNAME,
                                is_show_alias: filteredData[0].ShowAliasName,
                                status_id: 1001
                            });
                        }
                    }
                }
            }
            CustomFieldArray.forEach((x) => {
                if (x.field_name == 'tag_id') {
                    if (!ths.isBlank(x.field_value)) {
                        var val = "";
                        x.field_value.forEach((itm) => {
                            val += itm.value;
                            val += ',';
                        });
                        x.field_value = val;
                    }
                }
                if (x.field_name == 'is_ongoing' || x.field_name == 'is_hourly' || x.field_name == 'is_billable') {
                    if (x.field_value == null || x.field_value == '') {
                        x.field_value = 0;
                    }
                }
                if (x.field_name == 'planned_start_date') {
                    x.field_value = ths.$options.filters.formatDate(new Date(x.field_value));
                }
                 if (x.field_name == 'planned_end_date') {
                    x.field_value = ths.$options.filters.formatDate(new Date(x.field_value));
                }

                if (x.field_name == 'modified_by') {
                    x.field_value = ths.userId;
                }
                if (x.field_name == 'created_by') {
                    x.field_value = ths.userId;
                }
                if (x.field_name == 'project_description') {
                    x.field_value = ths.Descriptionn;
                }
                if (x.field_name == 'project_team') {
                    x.field_value = team;
                }
                if (x.field_name == 'project_tab') {
                   x.field_value = this.viewsAndTabs.filter(tab => this.form.selectedTabs.includes(tab.id));
                }
                if (ths.ProjectId > 0) {
                    if (x.field_name == 'industry_type_id') {
                         x.field_value = ths.form.industryId;

                    }
                    if (x.field_name == 'template_id') {
                        x.field_value = ths.form.methodologyId;
                    }
                }
                else {
                    if (x.field_name == 'industry_type_id') {
                          x.field_value = ths.form.industryId;
                    }
                    if (x.field_name == 'template_id') {
                        x.field_value = ths.form.methodologyId;
                    }
                }
            });
            var obj = {
                data: CustomFieldArray,
                moduleCode: "PROJECT",
                subModuleCode: "PROJECT_DETAIL"
            }

            DataService.SaveDynamicForm(JSON.stringify(obj)).then(function (response) {
                if (response != null && response.data != null && response.data[0].Status == "Success") {
                    if (ths.ProjectId > 0) {
                        ths.ShowAlert(ths.$t('UpdatedSuccess', [ths.$t('Project')]), "success", true, ths.$t("Alert"));
                        if (ths.Type == 'Edit') {
                            ths.$parent.FetchData();
                            ths.$router.push({ name: 'ProjectList' });
                        } else {
                            ths.$parent.UpdateOverView();
                        }
                        ths.CloseTemplateNew();
                    }
                    else {
                        if (response.data[0].Value.MSG == 'DUPLICATE') {
                            ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Project')]), "warning", true, ths.$t("Alert"));
                        } else {                            
                            ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Project')]), "success", true, ths.$t("Alert"));
                            ths.$router.push({ name: 'ProjectDetail', params: { projectId: response.data[0].Value.MAIN_ID } });
                            ths.ProjectId = response.data[0].Value.MAIN_ID;
                            let projectNameField = CustomFieldArray.find(x => x.field_name === "project_name");
                            let projectName = projectNameField ? projectNameField.field_value : "";
                            let projectTeamField = CustomFieldArray.find(x => x.field_name === "project_team");
                            let projectTeam = projectTeamField ? projectTeamField.field_value : [];
                            let payload = {
                                projectId: ths.ProjectId,
                                projectName: projectName,
                                projectContent:ths.GetUserInfo.Name + ' has created a new project "' + projectName + '"',
                                projectTeam: projectTeam
                            };
                            DataService.SendAddProjectNotification(JSON.stringify(payload)).then((res) => {
                                
                            });
                        }

                    }
                }
            })
            ths.isLoading = false;
        },
        FetchProjectData: function () {
            var ths = this;
            ths.isLoading = true;
            var url = `recordId=${ths.ProjectId}&moduleName=PROJECT&subModuleCode=PROJECT_DETAIL`;
            DataService.GetDynamicForm(url).then(function (response) {
                if (response != null && response.data != null) {                    
                    ths.EventData = response.data.data;                   
                    ths.FormSchema = ths.$refs.AddProjectForm.ConvertCustomFieldIntoDynamicFormObj(ths.EventData);                    
                    ths.FormSchema.forEach((group) => {                                                
                        if(group.group_name == 'Project Description'){                             
                            group.layoutType='single';
                        }                       
                        group.Data.forEach((field) => {                             
                                 const visibleFieldNames = [
                                    'project_name',
                                    'planned_start_date',
                                    'planned_end_date',
                                    'priority_id',
                                    'status_id',
                                    'project_description'
                                ];
                                field.visibility = visibleFieldNames.includes(field.name);
                                field.validationRules.required= visibleFieldNames.includes(field.name);
                                const notRequiredFields = [
                                        'currency_id',
                                        'off_days',
