        validateStep(step) {
            if (step === 1) {
                if (!this.form.industryId || !this.form.methodologyId) {
                    this.ShowAlert('Please select industry and methodology.', 'failure', true, 'Alert');
                    return false;
                }
            }
            if (step === 2) {
                if (!this.form.projectName || !this.form.startDate || !this.form.endDate) {
                    this.ShowAlert('Please enter all required project details.', 'failure', true, 'Alert');
                    return false;
                }
                if (new Date(this.form.endDate) < new Date(this.form.startDate)) {
                    this.ShowAlert('End date should be greater than start date.', 'failure', true, 'Alert');
                    return false;
                }
            }
            if (step === 3 && !this.form.selectedTabs.length) {
                this.ShowAlert('Please select at least one tab.', 'failure', true, 'Alert');
                return false;
            }
            if (step === 4) {
                if (this.teamType === 'user') {
                    if (!this.form.selectedTeamIds.length) {
                        this.ShowAlert('Please select at least one team member.', 'failure', true, 'Alert');
                        return false;
                    }
                    if (!this.form.pmIds.length) {
                        this.ShowAlert('Please select at least one project manager.', 'failure', true, 'Alert');
                        return false;
                    }
                } else {
                    if (!this.form.selectedTeamGroupIds.length) {
                        this.ShowAlert('Please select at least one team.', 'failure', true, 'Alert');
                        return false;
                    }
                }
            }
            return true;
        },
